<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationAcceptedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationAcceptedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withAcceptedAt,
 * getAcceptedAt/acceptedAt accessors, and isAcceptedAtChanged with/without original.
 */
class UserInvitationAcceptedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAcceptedAt creates a new instance with the AcceptedAt set
     * from a string value, and getAcceptedAt returns the primitive string.
     */
    public function testWithAcceptedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedAtAccessorUnitTest();

        // Act
        $result = $holder->withAcceptedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getAcceptedAt());
    }
    /**
     * Asserts that withacceptedAt has access to the value object
     * from a string value, and getAcceptedAt returns the primitive string.
     */
    public function testWithAcceptedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedAtAccessorUnitTest();

        // Act
        $result = $holder->withAcceptedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->acceptedAt()->value());
    }
    public function testChangedAcceptedAt(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedAtAccessorUnitTest();
        $original = $holder->withAcceptedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withAcceptedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withAcceptedAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isAcceptedAtChanged();
        $withSame = $original->isAcceptedAtChanged($same);
        $withDiferent = $original->isAcceptedAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationAcceptedAtAccessorUnitTest
{
    use UserInvitationAcceptedAtAccessor;
}
